const PDFDocument = require('pdfkit');

const INK = '#0B1220';
const NAVY = '#0B1A33';
const BLUE = '#1769FF';
const BLUE_SOFT = '#EEF4FF';
const BLUE_LINE = '#D6E4FF';
const TEXT_SOFT = '#45566B';
const TEXT_MUTE = '#8296A8';
const LINE = '#E4E9F0';
const OK = '#1E9E63';

function money(amount, currency) {
  return `${currency} ${Number(amount).toLocaleString()}`;
}

/**
 * Renders a branded PDF receipt for a paid order.
 * order: { plan, amount, name, email, phone, domain, currency, method }
 * meta: { reference, paidAt (Date) }
 * Returns a Buffer.
 */
function generateReceiptPdf(order, meta) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: 'A4', margin: 0 });
    const chunks = [];
    doc.on('data', (c) => chunks.push(c));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    const pageW = doc.page.width;
    const pageH = doc.page.height;
    const marginX = 56;
    const innerW = pageW - marginX * 2;
    const currency = order.currency || 'ZMW';
    const paidDate = meta.paidAt.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    const method = order.method === 'card' ? 'Card' : 'Mobile Money';

    // header: blue accent strip, logo on the left, RECEIPT + reference on the right
    doc.rect(0, 0, pageW, 8).fill(BLUE);
    doc.image(LOGO, marginX, 36, { width: 190 });

    doc.fillColor(NAVY).font('Helvetica-Bold').fontSize(26).text('RECEIPT', 0, 42, { align: 'right', width: pageW - marginX });
    doc.fillColor(TEXT_MUTE).font('Helvetica').fontSize(10)
      .text(meta.reference, 0, 76, { align: 'right', width: pageW - marginX })
      .text(paidDate, 0, 90, { align: 'right', width: pageW - marginX });

    doc.moveTo(marginX, 130).lineTo(pageW - marginX, 130).strokeColor(LINE).lineWidth(1).stroke();

    // paid badge
    let y = 150;
    doc.roundedRect(marginX, y, 78, 24, 12).fill(OK);
    doc.fillColor('#FFFFFF').font('Helvetica-Bold').fontSize(11).text('PAID', marginX, y + 7, { width: 78, align: 'center' });
    doc.fillColor(TEXT_SOFT).font('Helvetica').fontSize(10.5).text('Payment received. Thank you!', marginX + 92, y + 7);

    // billed to / order details
    y += 52;
    const col2 = pageW / 2 + 10;
    doc.fillColor(BLUE).font('Helvetica-Bold').fontSize(9).text('BILLED TO', marginX, y);
    doc.fillColor(BLUE).font('Helvetica-Bold').fontSize(9).text('ORDER DETAILS', col2, y);

    y += 16;
    doc.fillColor(INK).font('Helvetica-Bold').fontSize(12).text(order.name || '-', marginX, y, { width: col2 - marginX - 20 });
    const details = [['Reference', meta.reference], ['Date', paidDate], ['Payment method', method]];
    details.forEach(([label, value], i) => {
      doc.fillColor(TEXT_MUTE).font('Helvetica-Bold').fontSize(9).text(label, col2, y + 1 + i * 17);
      doc.fillColor(INK).font('Helvetica').fontSize(10).text(value, col2 + 88, y + i * 17, { width: pageW - marginX - col2 - 88 });
    });
    doc.fillColor(TEXT_SOFT).font('Helvetica').fontSize(10).text(order.email || '-', marginX, y + 18);
    if (order.phone) doc.fillColor(TEXT_SOFT).font('Helvetica').fontSize(10).text(order.phone, marginX, y + 34);

    // line item table
    y += 82;
    doc.roundedRect(marginX, y, innerW, 30, 6).fill(NAVY);
    doc.fillColor('#FFFFFF').font('Helvetica-Bold').fontSize(9)
      .text('DESCRIPTION', marginX + 16, y + 11)
      .text('AMOUNT', 0, y + 11, { align: 'right', width: pageW - marginX - 16 });

    y += 30;
    doc.fillColor(INK).font('Helvetica-Bold').fontSize(11.5).text(order.plan, marginX + 16, y + 16, { width: innerW - 180 });
    if (order.domain) {
      doc.fillColor(TEXT_MUTE).font('Helvetica').fontSize(9.5).text(`Domain: ${order.domain}`, marginX + 16, y + 32);
    }
    doc.fillColor(INK).font('Helvetica-Bold').fontSize(11.5).text(money(order.amount, currency), 0, y + 16, { align: 'right', width: pageW - marginX - 16 });
    y += order.domain ? 54 : 46;
    doc.moveTo(marginX, y).lineTo(pageW - marginX, y).strokeColor(LINE).lineWidth(1).stroke();

    // total box
    y += 18;
    const boxW = 250;
    const boxX = pageW - marginX - boxW;
    doc.roundedRect(boxX, y, boxW, 52, 8).fillAndStroke(BLUE_SOFT, BLUE_LINE);
    doc.fillColor(TEXT_SOFT).font('Helvetica-Bold').fontSize(10).text('TOTAL PAID', boxX + 16, y + 20);
    doc.fillColor(BLUE).font('Helvetica-Bold').fontSize(18).text(money(order.amount, currency), boxX, y + 16, { align: 'right', width: boxW - 16 });

    // footer: thank-you line and a navy contact band
    const bandH = 84;
    const bandY = pageH - bandH;
    doc.fillColor(NAVY).font('Helvetica-Bold').fontSize(12).text('Thank you for choosing Nadine Cloud.', marginX, bandY - 44);
    doc.fillColor(TEXT_MUTE).font('Helvetica').fontSize(9.5).text('Keep this receipt for your records. Questions? Reply to your receipt email or contact us below.', marginX, bandY - 26, { width: innerW });

    doc.rect(0, bandY, pageW, bandH).fill(NAVY);
    doc.rect(0, bandY, pageW, 4).fill(BLUE);
    doc.fillColor('#FFFFFF').font('Helvetica-Bold').fontSize(12).text('Nadine Cloud', marginX, bandY + 20);
    doc.fillColor('#8FB8FF').font('Helvetica').fontSize(9).text('One Cloud. Endless Possibilities.', marginX, bandY + 37);
    doc.fillColor('#C7D3E6').font('Helvetica').fontSize(9)
      .text('info@nadinecloud.com  ·  +260 964 068 483', 0, bandY + 22, { align: 'right', width: pageW - marginX })
      .text('www.nadinecloud.com  ·  PHI Mall, Lusaka, Zambia', 0, bandY + 37, { align: 'right', width: pageW - marginX });

    doc.end();
  });
}

// Official Nadine Cloud logo (JPEG, 720px wide), kept inline so the deploy doesn't need an extra asset file.
const LOGO = Buffer.from('', 'base64');

module.exports = { generateReceiptPdf };
